import java.util.Scanner;

public class Main {
    static long[] powers_of_ten = new long[18];
    static int answer = 0;

    static void search(int current_sum, long remaining, int position) {
        if (current_sum > answer)
            return;
        if (remaining == 0) {
            answer = Math.min(answer, current_sum);
            return;
        }
        long count = remaining / powers_of_ten[position];
        // First recursive call: add position * count, then recurse
        search(current_sum + (int)(position * count), remaining - count * powers_of_ten[position], position - 1);
        // Second recursive call: add count * position, then recurse
        search(current_sum + (int)(count * position), count * powers_of_ten[position] - remaining, position - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long num = sc.nextLong();

        powers_of_ten[1] = 1;
        for (int i = 2; i < 18; i++) {
            powers_of_ten[i] = 10 * powers_of_ten[i - 1] + 1;
        }

        long temp_num = num;
        answer = 0;
        while (temp_num > 0) {
            for (int i = 1; i < 18; i++) {
                if (powers_of_ten[i] > temp_num) {
                    answer += (i - 1);
                    temp_num -= powers_of_ten[i - 1];
                    break;
                }
            }
        }

        search(0, num, 16);
        System.out.println(answer);
        sc.close();
    }
}
